SELECT t.id AS id, t.tb_name AS name, 'table' AS type FROM olap_table_pro t JOIN olap_table_field_mapping map ON t.id = map.table_id JOIN olap_basic_pro basic ON map.basic_id = basic.id WHERE t.tb_type_key IN (0, 1) AND t.status = 3 AND map.status = 1 AND basic.category = 1 AND basic.status = 2 AND map.basic_id IN
#{id}
AND t.id IN
#{id}
GROUP BY t.id, t.tb_name HAVING COUNT(DISTINCT map.basic_id) = #{dimensionSize}
UNION ALL
SELECT dm.id AS id, dm.name AS name, 'model' AS type FROM olap_data_model dm LEFT JOIN olap_data_model_dimension dmd ON dmd.model_id = dm.id JOIN olap_table_pro t ON t.id = dm.fact_table_id OR t.id = dmd.dim_table_id JOIN olap_table_field_mapping map ON t.id = map.table_id JOIN olap_basic_pro basic ON map.basic_id = basic.id WHERE dm.status = 1 AND t.status = 3 AND map.status = 1 AND basic.category = 1 AND basic.status = 2 AND map.basic_id IN
#{id}
AND dm.id IN
#{id}
GROUP BY dm.id, dm.name HAVING COUNT(DISTINCT map.basic_id) = #{dimensionSize}
